import "server-only";
import { getServerSupabase } from "@/lib/supabase/server";
import { isUuid } from "./professional-profile";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "@/types/database.types";

// Additive migration contract, isolated while the generated database file is
// being regenerated by the parallel account-settings work.
type RoutesDatabase = Omit<Database, "public"> & {public: Database["public"] & {
  Views: Database["public"]["Views"] & {profile_public_routes: {
    Row: {id: string | null; persona: string | null; username: string | null}; Relationships: [];
  }};
}};
async function routeClient() {
  return await getServerSupabase() as unknown as SupabaseClient<RoutesDatabase>;
}

const HANDLE = /^[a-z][a-z0-9]*([._][a-z0-9]+)*$/;
export function validPublicHandle(value: string) {
  return value.length >= 3 && value.length <= 24 && HANDLE.test(value);
}
export function publicProfileHref(route: {persona: string; username: string}) {
  return `/p/${encodeURIComponent(route.persona)}/${encodeURIComponent(route.username)}`;
}
export async function publicRouteById(id: string) {
  if (!isUuid(id)) return null;
  const db = await routeClient();
  const {data, error} = await db.from("profile_public_routes").select("id, persona, username").eq("id", id).maybeSingle();
  return error || !data?.id || !data.persona || !data.username ? null : {id: data.id, persona: data.persona, username: data.username};
}
export async function resolvePublicRoute(persona: string, username: string) {
  if (!/^[a-z][a-z_]{1,39}$/.test(persona) || !validPublicHandle(username.toLowerCase())) return null;
  const db = await routeClient();
  const {data, error} = await db.from("profile_public_routes").select("id, persona, username").eq("persona", persona).eq("username", username.toLowerCase()).maybeSingle();
  return error || !data?.id || !data.persona || !data.username ? null : {id: data.id, persona: data.persona, username: data.username};
}
